"""Finite-state controller for server-controlled solo bots.

`tick_bots` runs once per engine tick, after lifecycle and before movement, combat timers and
the zone. It only decides and sets intents through the same verbs a human has (move intent,
sprint, stance, yaw, air steer, jump, parachute, pickup, equip, attach, fire, reload, heal,
throw, vehicle enter/exit). It never writes positions, health, ammo or inventory directly.

Scheduling: a bot makes a full decision when `match.clock >= brain.next_decision_at`. The
interval is the profile's `decision_interval` while a human is within HUMAN_NEAR metres and
`far_decision_interval` otherwise, with jitter so bots spread across ticks. Between decisions a
bot keeps its intent and only does cheap per-tick work: steering along its path, tracking and
firing at an acquired target, and airborne control.

Decision priority (first match wins):
  eliminated > airborne states > urgent zone escape > retreat > take cover / engage > heal >
  reload > loot (when poorly equipped, or opportunistically close by) > non-urgent zone escape
  (via a nearby vehicle when the zone is far) > investigate last known target > explore/patrol.

All tuning numbers are development values, not original Rules of Survival behaviour.
"""

import math
from dataclasses import dataclass

from solo_engine import combat, items, lifecycle, loot, maps, movement, zone
from solo_engine.bots import navigation, perception
from solo_engine.bots.perception import BlockerIndex, MatchMemory
from solo_engine.geometry import SpatialGrid, distance, normalize
from solo_engine.model import (
    BotBrain,
    BotState,
    GroundLoot,
    LifeState,
    MatchPhase,
    Participant,
    SoloMatch,
    Stance,
)

HUMAN_NEAR = 150.0  # metres: a human this close makes the bot decide at decision_interval
DECISION_JITTER = (0.75, 1.25)
UNDER_FIRE_SECONDS = 2.5
LOST_TARGET_RECHECK = 0.25  # seconds until the next decision after losing a target
TRACK_EVERY_TICKS = 4  # between shots, re-verify an acquired target this often
DEPLOY_HEIGHT = {"easy": 320.0, "normal": 230.0, "hard": 170.0}
LANDING_REACH_SAFETY = 0.85
LANDING_CROWD_EXPONENT = 2.0  # POI weight / (1 + bots that already chose it) ** this
SPAWN_LANDING_CHANCE = 0.25  # chance to land at a reachable loot spawn instead of a POI pick
OUTSKIRT_LANDING_CHANCE = 0.5  # chance to land on open ground away from every POI
OUTSKIRT_GAP = 60.0  # metres beyond a POI radius that count as away from it
LANDING_SAMPLES = 8  # candidate points; the one farthest from other bots' targets wins
OPPORTUNISTIC_LOOT = 15.0  # metres: a well-equipped bot still grabs useful loot this close
LOOT_LOS_CANDIDATES = 4
INVESTIGATE_RANGE = 80.0
INVESTIGATE_DONE = 4.0
PATROL_RADIUS = (15.0, 40.0)
RETREAT_STEP = 25.0
VEHICLE_SEARCH = 15.0
VEHICLE_ZONE_DISTANCE = 300.0
VEHICLE_EXIT_INSIDE = 30.0
GRENADE_RANGE = (8.0, 30.0)
MAX_HEAL_ITEMS = 6
AMMO_MAGS_WANTED = 3

WEAPON_SCORE = {"assault_rifle": 5.0, "smg": 4.0, "shotgun": 3.5, "sniper": 3.0, "pistol": 1.0}
PREFERRED_RANGE = {
    "pistol": (5.0, 20.0),
    "smg": (6.0, 30.0),
    "shotgun": (2.0, 10.0),
    "assault_rifle": (12.0, 60.0),
    "sniper": (40.0, 120.0),
}
_AIRBORNE = (LifeState.FREEFALL, LifeState.PARACHUTE)
_REPORT_ARRIVAL = frozenset(
    {
        BotState.LOOTING,
        BotState.EXPLORING,
        BotState.PATROLLING,
        BotState.ZONE_ESCAPE,
        BotState.TAKING_COVER,
        BotState.RETREATING,
        BotState.DRIVING,
    }
)
_NO_SPRINT = frozenset({BotState.ENGAGING, BotState.HEALING})


@dataclass
class _Ctx:
    match: SoloMatch
    grid: SpatialGrid
    dt: float
    now: float
    index: BlockerIndex
    mem: MatchMemory
    humans: list[tuple[float, float]]


# =========================================================================== entry point


def tick_bots(match: SoloMatch, grid: SpatialGrid, dt: float) -> None:
    """Decide and set intents for every bot in the match. Never moves anyone directly."""
    if match.phase == MatchPhase.CLOSED:
        return
    if not isinstance(dt, (int, float)) or not math.isfinite(dt) or dt <= 0:
        return
    mem = perception.memory(match)
    perception.absorb_damage_events(match, mem)
    ctx = _Ctx(
        match=match,
        grid=grid,
        dt=float(dt),
        now=match.clock,
        index=perception.blocker_index(match.map),
        mem=mem,
        humans=[(p.x, p.y) for p in match.participants.values() if not p.is_bot and p.alive],
    )
    rng = match.rng
    for p in match.participants.values():
        brain = p.brain
        if brain is None or not p.is_bot:
            continue
        if not p.alive:
            if brain.state != BotState.ELIMINATED:
                brain.state = BotState.ELIMINATED
                brain.target_id = None
                brain.destination = None
                brain.path.clear()
                navigation.stop(p)
            continue
        if ctx.now >= brain.next_decision_at:
            profile = brain.profile
            interval = profile.decision_interval if _human_near(ctx, p) else profile.far_decision_interval
            brain.next_decision_at = ctx.now + interval * rng.uniform(*DECISION_JITTER)
            _decide(ctx, p, brain)
        _act(ctx, p, brain)


def _human_near(ctx: _Ctx, p: Participant) -> bool:
    r2 = HUMAN_NEAR * HUMAN_NEAR
    return any((hx - p.x) ** 2 + (hy - p.y) ** 2 <= r2 for hx, hy in ctx.humans)


# =========================================================================== decisions


def _decide(ctx: _Ctx, p: Participant, b: BotBrain) -> None:
    life = p.life
    if life == LifeState.WAITING:
        _decide_waiting(ctx, p, b)
        return
    if life == LifeState.ON_AIRCRAFT:
        if b.state != BotState.AIRCRAFT:
            b.state = BotState.AIRCRAFT
            navigation.clear(b, p, ctx.now)
        if b.landing_target is None:
            b.landing_target = _choose_landing(ctx, p, b)
        return
    if life in _AIRBORNE:
        b.state = BotState.PARACHUTING
        if b.landing_target is None:
            b.landing_target = (p.x, p.y)
        return
    if b.state in (BotState.WAITING, BotState.AIRCRAFT, BotState.PARACHUTING):
        b.state = BotState.LOOTING  # just landed
        navigation.clear(b, p, ctx.now)
    if life == LifeState.IN_VEHICLE:
        _decide_vehicle(ctx, p, b)
        return
    _decide_grounded(ctx, p, b)


def _decide_waiting(ctx: _Ctx, p: Participant, b: BotBrain) -> None:
    b.state = BotState.WAITING
    rng = ctx.match.rng
    if b.path and rng.random() < 0.7:
        return
    if rng.random() < 0.4:
        dest = maps.random_open_point(ctx.match.map, rng, within=ctx.match.map.prep_island)
        navigation.set_destination(b, p, ctx.index, ctx.match.map, dest, ctx.now, straight=True)
    else:
        navigation.clear(b, p, ctx.now)


def _choose_landing(ctx: _Ctx, p: Participant, b: BotBrain) -> tuple[float, float]:
    """A landing point reachable from the bot's planned jump point, on open ground.

    Bots spread out instead of all diving into the same towns:
    - with chance SPAWN_LANDING_CHANCE the bot lands at a reachable world loot spawn (these lie
      in and around towns), sampled LANDING_SAMPLES times and taking the one farthest from the
      targets other bots already chose;
    - otherwise it picks a reachable POI, weighted by loot_weight / (1 + picks) **
      LANDING_CROWD_EXPONENT where picks counts bots that already chose that POI, and lands at
      the best-spaced of LANDING_SAMPLES open points inside it.
    """
    match = ctx.match
    rng = match.rng
    game_map = match.map
    config = match.config
    aircraft = match.aircraft
    if aircraft is None:
        return p.x, p.y
    t = min(max(b.jump_at_progress, 0.0), 1.0)
    jx = aircraft.start[0] + (aircraft.end[0] - aircraft.start[0]) * t
    jy = aircraft.start[1] + (aircraft.end[1] - aircraft.start[1]) * t
    deploy = min(DEPLOY_HEIGHT.get(b.profile.name, 230.0), aircraft.altitude)
    freefall = (aircraft.altitude - deploy) / max(config.freefall_speed, 1e-6) * config.freefall_glide
    canopy = deploy / max(config.parachute_speed, 1e-6) * config.parachute_glide
    reach = (freefall + canopy) * LANDING_REACH_SAFETY
    picks = ctx.mem.landing_picks
    taken = ctx.mem.landing_points

    def spacing(x: float, y: float) -> float:
        return min(((x - tx) ** 2 + (y - ty) ** 2 for tx, ty in taken), default=math.inf)

    def remember(point: tuple[float, float]) -> tuple[float, float]:
        nearest = min(game_map.pois, key=lambda poi: distance(point[0], point[1], poi.x, poi.y), default=None)
        if nearest is not None and distance(point[0], point[1], nearest.x, nearest.y) <= nearest.radius:
            picks[nearest.name] = picks.get(nearest.name, 0) + 1
        taken.append(point)
        return point

    r2 = reach * reach
    roll = rng.random()
    if roll < OUTSKIRT_LANDING_CHANCE:
        points = []
        for _ in range(LANDING_SAMPLES * 4):
            angle = rng.uniform(0.0, math.tau)
            r = reach * math.sqrt(rng.random())
            x, y = jx + math.cos(angle) * r, jy + math.sin(angle) * r
            if any(distance(x, y, poi.x, poi.y) < poi.radius + OUTSKIRT_GAP for poi in game_map.pois):
                continue
            if navigation.is_open(game_map, x, y):
                points.append((x, y))
                if len(points) >= LANDING_SAMPLES:
                    break
        if points:
            return remember(max(points, key=lambda s: spacing(*s)))
    elif roll < OUTSKIRT_LANDING_CHANCE + SPAWN_LANDING_CHANCE:
        spawns = [(x, y) for x, y in game_map.loot_spawns if (x - jx) ** 2 + (y - jy) ** 2 <= r2]
        if spawns:
            sample = [rng.choice(spawns) for _ in range(LANDING_SAMPLES)]
            sample = [s for s in sample if navigation.is_open(game_map, *s)]
            if sample:
                return remember(max(sample, key=lambda s: spacing(*s)))
    pois = [poi for poi in game_map.pois if distance(jx, jy, poi.x, poi.y) <= reach]
    if pois:
        weights = [max(poi.loot_weight, 0.01) / (1 + picks.get(poi.name, 0)) ** LANDING_CROWD_EXPONENT for poi in pois]
        poi = rng.choices(pois, weights=weights, k=1)[0]
        points = []
        for _ in range(LANDING_SAMPLES):
            angle = rng.uniform(0.0, math.tau)
            r = poi.radius * 0.7 * math.sqrt(rng.random())
            x, y = poi.x + math.cos(angle) * r, poi.y + math.sin(angle) * r
            if navigation.is_open(game_map, x, y):
                points.append((x, y))
        if points:
            return remember(max(points, key=lambda s: spacing(*s)))
        point = navigation.open_point_near(game_map, poi.x, poi.y, rng, radius=poi.radius)
        if point is not None:
            return remember(point)
    for _ in range(40):
        angle = rng.uniform(0.0, math.tau)
        r = reach * math.sqrt(rng.random())
        x, y = jx + math.cos(angle) * r, jy + math.sin(angle) * r
        if navigation.is_open(game_map, x, y):
            return remember((x, y))
    return remember(lifecycle.find_free_point(game_map, jx, jy))


def _decide_grounded(ctx: _Ctx, p: Participant, b: BotBrain) -> None:
    match = ctx.match
    now = ctx.now
    profile = b.profile
    _manage_weapons(p)

    # With bot_combat off (gateway Phase A) a bot perceives no opponent, so it never engages,
    # retreats from, or investigates anyone; it still loots, explores and follows the zone.
    combat_on = match.config.bot_combat
    enemies = perception.visible_opponents(match, ctx.grid, ctx.index, p, now) if combat_on else []
    target = _pick_target(b, enemies)
    if target is not None:
        if target.participant_id != b.target_id:
            b.target_id = target.participant_id
            b.target_seen_at = now
        b.last_known_target = (target.x, target.y)
    else:
        b.target_id = None
    armed = _usable_slot(p) is not None
    under_fire = b.last_damaged_at >= 0 and now - b.last_damaged_at <= UNDER_FIRE_SECONDS
    attacker = _known_attacker(match, p, b) if under_fire and combat_on else None

    # urgent zone escape
    if _zone_urgent(match, p, b):
        _go_zone(ctx, p, b)
        return

    # retreat: badly hurt while engaged, or unarmed and threatened
    threat = target or attacker
    if threat is not None and not armed and p.health >= profile.retreat_threshold:
        item = _find_loot(ctx, p, perception.LOOT_SIGHT)
        if item is not None:  # race for gear rather than run
            _go_loot(ctx, p, b, item)
            return
    if threat is not None and _active_slot(threat) is not None and (p.health < profile.retreat_threshold or not armed):
        _retreat(ctx, p, b, threat)
        return

    # take cover (state set when a new engagement's first hit rolled cover_chance)
    if b.state == BotState.TAKING_COVER:
        if under_fire and b.destination is None and threat is not None:
            spot = navigation.cover_point(ctx.index, match.map, p, threat.x, threat.y)
            if spot is not None:
                navigation.set_destination(b, p, ctx.index, match.map, spot, now)
                movement.set_stance(p, Stance.STAND)
                return
        elif under_fire and b.path:
            return
        b.state = BotState.PATROLLING

    if target is not None and armed:
        _engage(ctx, p, b, target)
        return

    # heal
    if p.healing_item is not None:
        b.state = BotState.HEALING
        navigation.clear(b, p, now)
        return
    if p.health < profile.heal_threshold and not under_fire:
        item = _best_heal(p)
        if item is not None and combat.start_heal(p, item)[0]:
            b.state = BotState.HEALING
            navigation.clear(b, p, now)
            return

    # reload
    if p.reload_left > 0:
        b.state = BotState.RELOADING
        return
    if _wants_reload(p) and combat.start_reload(p)[0]:
        b.state = BotState.RELOADING
        return

    # loot
    radius = perception.LOOT_SIGHT if _poorly_equipped(p) else OPPORTUNISTIC_LOOT
    item = _find_loot(ctx, p, radius)
    if item is not None:
        _go_loot(ctx, p, b, item)
        return

    # non-urgent zone escape
    if _outside_next_with_margin(match, p, b):
        _go_zone(ctx, p, b)
        return

    # investigate the last known target position
    if b.last_known_target is not None:
        lx, ly = b.last_known_target
        d = distance(p.x, p.y, lx, ly)
        if INVESTIGATE_DONE < d <= INVESTIGATE_RANGE:
            _maybe_grenade(ctx, p, lx, ly, chance=0.3)
            b.state = BotState.PATROLLING
            if b.destination != (lx, ly):
                navigation.set_destination(b, p, ctx.index, match.map, (lx, ly), now)
            return
        b.last_known_target = None

    _explore(ctx, p, b)


def _pick_target(b: BotBrain, enemies: list[Participant]) -> Participant | None:
    if not enemies:
        return None
    for preferred in (b.target_id, b.last_attacker_id):
        if preferred:
            for enemy in enemies:
                if enemy.participant_id == preferred:
                    return enemy
    return enemies[0]


def _known_attacker(match: SoloMatch, p: Participant, b: BotBrain) -> Participant | None:
    """The participant that just hit this bot, located because the hit gave it away."""
    attacker = match.participants.get(b.last_attacker_id or "")
    if attacker is None or not attacker.alive or attacker.life not in perception.PERCEIVABLE:
        return None
    reach = b.profile.view_distance * perception.ATTACKER_RANGE_FACTOR
    if combat.distance3d(p, attacker) > reach:
        return None
    return attacker


# --------------------------------------------------------------------------- engagement


def _engage(ctx: _Ctx, p: Participant, b: BotBrain, target: Participant) -> None:
    match = ctx.match
    rng = match.rng
    b.state = BotState.ENGAGING
    slot = _active_slot(p)
    weapon = items.WEAPONS.get(slot.weapon_id) if slot is not None else None
    if weapon is None:
        return
    near, far = PREFERRED_RANGE.get(weapon.weapon_id, (5.0, 30.0))
    reach = min(far, weapon.range * 0.9)
    d = distance(p.x, p.y, target.x, target.y)
    dx, dy = normalize(target.x - p.x, target.y - p.y)
    if dx == 0.0 and dy == 0.0:
        dx, dy = math.cos(p.yaw), math.sin(p.yaw)
    push = rng.random() < b.profile.aggression
    dest: tuple[float, float] | None = None
    if d > reach and (push or d > weapon.range * 0.95):
        step = min(d - reach * 0.8, 25.0)
        dest = (p.x + dx * step, p.y + dy * step)
    elif d < near:
        dest = (p.x - dx * 4.0, p.y - dy * 4.0)
    elif push and rng.random() < 0.6:
        side = 1.0 if rng.random() < 0.5 else -1.0
        reach_side = rng.uniform(2.0, 5.0)
        dest = (p.x - dy * side * reach_side, p.y + dx * side * reach_side)
    if (
        dest is not None
        and navigation.is_open(match.map, dest[0], dest[1])
        and ctx.index.los(p.x, p.y, dest[0], dest[1])
    ):
        if p.stance != Stance.STAND:
            movement.set_stance(p, Stance.STAND)
        navigation.set_destination(b, p, ctx.index, match.map, dest, ctx.now, straight=True)
    else:
        navigation.clear(b, p, ctx.now)
        if p.stance == Stance.STAND and rng.random() < 0.5:
            movement.set_stance(p, Stance.CROUCH)
    p.yaw = math.atan2(dy, dx)
    if rng.random() < 0.1:
        _maybe_grenade(ctx, p, target.x, target.y, chance=1.0)


def _retreat(ctx: _Ctx, p: Participant, b: BotBrain, threat: Participant) -> None:
    match = ctx.match
    b.state = BotState.RETREATING
    ax, ay = normalize(p.x - threat.x, p.y - threat.y)
    if ax == 0.0 and ay == 0.0:
        ax, ay = math.cos(p.yaw + math.pi), math.sin(p.yaw + math.pi)
    circle = _safe_circle(match)
    if circle is not None:
        zx, zy = normalize(circle[0] - p.x, circle[1] - p.y)
        ax, ay = normalize(ax + 0.6 * zx, ay + 0.6 * zy)
        if ax == 0.0 and ay == 0.0:
            ax, ay = zx, zy
    if b.path and b.destination is not None:
        cx, cy = b.destination
        if (cx - p.x) * ax + (cy - p.y) * ay > 5.0:
            return  # still heading away
    if p.stance != Stance.STAND:
        movement.set_stance(p, Stance.STAND)
    spot = navigation.open_point_near(
        match.map, p.x + ax * RETREAT_STEP, p.y + ay * RETREAT_STEP, match.rng, radius=8.0
    )
    if spot is None:
        navigation.clear(b, p, ctx.now)
        return
    navigation.set_destination(b, p, ctx.index, match.map, spot, ctx.now)


def _fire_at_target(ctx: _Ctx, p: Participant, b: BotBrain) -> None:
    """Per tick: keep tracking the acquired target and fire when every rule allows it.

    Line of sight is verified right before every shot. Between shots the (comparatively costly)
    tracking check runs every TRACK_EVERY_TICKS ticks, staggered by slot.
    """
    match = ctx.match
    target = match.participants.get(b.target_id or "")
    if target is None or not target.alive or not match.config.bot_combat:
        _lose_target(ctx, b)
        return
    slot = _active_slot(p)
    weapon = items.WEAPONS.get(slot.weapon_id) if slot is not None else None
    can_shoot = (
        p.life == LifeState.GROUNDED
        and p.healing_item is None
        and p.reload_left <= 0
        and weapon is not None
    )
    if can_shoot and slot.mag <= 0:
        if p.inventory.backpack.get(weapon.ammo_id, 0) > 0:
            combat.start_reload(p)
        else:
            _manage_weapons(p)
        can_shoot = False
    ready = can_shoot and p.fire_cooldown <= 0 and ctx.now >= b.target_seen_at + b.profile.reaction_time
    if not ready and (match.tick + p.slot) % TRACK_EVERY_TICKS != 0:
        return
    if not perception.can_track(ctx.index, p, target):
        _lose_target(ctx, b)
        return
    b.last_known_target = (target.x, target.y)
    if p.move_x == 0.0 and p.move_y == 0.0:
        p.yaw = math.atan2(target.y - p.y, target.x - p.x)
    if ready and combat.distance3d(p, target) <= weapon.range:
        combat.fire(match, p, target.x, target.y, target.participant_id, roll=match.rng.random())


def _lose_target(ctx: _Ctx, b: BotBrain) -> None:
    b.target_id = None
    b.next_decision_at = min(b.next_decision_at, ctx.now + LOST_TARGET_RECHECK)


def _maybe_grenade(ctx: _Ctx, p: Participant, x: float, y: float, chance: float) -> None:
    if not ctx.match.config.bot_combat:
        return
    if p.life != LifeState.GROUNDED or p.inventory.backpack.get("frag", 0) <= 0:
        return
    d = distance(p.x, p.y, x, y)
    if not GRENADE_RANGE[0] <= d <= GRENADE_RANGE[1]:
        return
    if ctx.match.rng.random() < chance:
        combat.throw_grenade(ctx.match, p, x, y, "frag")


# --------------------------------------------------------------------------- inventory


def _active_slot(p: Participant):
    inv = p.inventory
    if inv.active_slot is None or not 0 <= inv.active_slot < len(inv.weapons):
        return None
    return inv.weapons[inv.active_slot]


def _ammo_for(p: Participant, weapon_id: str) -> int:
    weapon = items.WEAPONS.get(weapon_id)
    return p.inventory.backpack.get(weapon.ammo_id, 0) if weapon is not None else 0


def _usable_slot(p: Participant) -> int | None:
    """Index of the best weapon that has rounds in the magazine or in the backpack."""
    best: int | None = None
    best_score = -math.inf
    for i, slot in enumerate(p.inventory.weapons):
        if slot is None or slot.weapon_id not in items.WEAPONS:
            continue
        if slot.mag <= 0 and _ammo_for(p, slot.weapon_id) <= 0:
            continue
        score = WEAPON_SCORE.get(slot.weapon_id, 1.0) + (0.5 if slot.mag > 0 else 0.0)
        if score > best_score:
            best, best_score = i, score
    return best


def _manage_weapons(p: Participant) -> None:
    """Hold the best usable weapon and fit carried attachments."""
    inv = p.inventory
    if p.reload_left <= 0 and p.healing_item is None:
        best = _usable_slot(p)
        if best is not None and best != inv.active_slot:
            loot.equip_weapon(p, best)
    attachments = [item_id for item_id in inv.backpack if item_id in items.ATTACHMENTS]
    for attachment_id in sorted(attachments):
        spec = items.ATTACHMENTS[attachment_id]
        for i, slot in enumerate(inv.weapons):
            if slot is not None and spec.slot not in slot.attachments and items.is_compatible(slot.weapon_id, attachment_id):
                loot.attach(p, i, attachment_id)
                break


def _wants_reload(p: Participant) -> bool:
    slot = _active_slot(p)
    if slot is None or slot.weapon_id not in items.WEAPONS:
        return False
    if _ammo_for(p, slot.weapon_id) <= 0:
        return False
    return slot.mag < items.mag_capacity(slot) * 0.5


def _heal_count(p: Participant) -> int:
    return sum(q for item_id, q in p.inventory.backpack.items() if item_id in items.HEALS)


def _best_heal(p: Participant) -> str | None:
    h = p.health
    if h < 40:
        order = ("medkit", "first_aid_kit", "bandage", "energy_drink")
    elif h < 75:
        order = ("first_aid_kit", "bandage", "medkit", "energy_drink")
    else:
        order = ("medkit", "energy_drink")
    backpack = p.inventory.backpack
    for item_id in order:
        spec = items.HEALS[item_id]
        if backpack.get(item_id, 0) > 0 and (spec.boost > 0 or h < min(spec.cap, p.max_health)):
            return item_id
    return None


def _poorly_equipped(p: Participant) -> bool:
    best = _usable_slot(p)
    if best is None:
        return True
    slot = p.inventory.weapons[best]
    if slot.mag + _ammo_for(p, slot.weapon_id) < items.WEAPONS[slot.weapon_id].mag_size:
        return True
    return p.inventory.armor_id is None or _heal_count(p) == 0


def _fits_one(p: Participant, item_id: str) -> bool:
    unit = items.item_space(item_id)
    return unit <= 0 or loot.backpack_capacity(p) - loot.backpack_used(p) >= unit - 1e-9


def _level(table: dict, item_id: str | None) -> int:
    spec = table.get(item_id or "")
    return spec.level if spec is not None else 0


def loot_score(p: Participant, item_id: str) -> float:
    """How much the bot wants one ground item now; 0 means leave it."""
    kind = items.kind_of(item_id)
    inv = p.inventory
    backpack = inv.backpack
    if kind == items.KIND_WEAPON:
        carried = [s for s in inv.weapons if s is not None]
        if any(s.weapon_id == item_id for s in carried):
            return 0.0
        base = WEAPON_SCORE.get(item_id, 1.0)
        if len(carried) < len(inv.weapons):
            return base + (4.0 if _usable_slot(p) is None else 0.0)
        worst = min(WEAPON_SCORE.get(s.weapon_id, 1.0) for s in carried)
        return base - worst if base - worst >= 1.0 else 0.0
    if kind == items.KIND_AMMO:
        best = 0.0
        for slot in inv.weapons:
            spec = items.WEAPONS.get(slot.weapon_id) if slot is not None else None
            if spec is None or spec.ammo_id != item_id:
                continue
            have = backpack.get(item_id, 0)
            if have < spec.mag_size * AMMO_MAGS_WANTED:
                best = max(best, 3.0 + (3.0 if slot.mag == 0 and have == 0 else 0.0))
        return best if best > 0 and _fits_one(p, item_id) else 0.0
    if kind == items.KIND_ARMOR:
        diff = _level(items.ARMORS, item_id) - _level(items.ARMORS, inv.armor_id)
        return 2.0 + diff if diff > 0 else 0.0
    if kind == items.KIND_HELMET:
        diff = _level(items.HELMETS, item_id) - _level(items.HELMETS, inv.helmet_id)
        return 1.5 + diff if diff > 0 else 0.0
    if kind == items.KIND_BACKPACK:
        diff = _level(items.BACKPACKS, item_id) - _level(items.BACKPACKS, inv.backpack_id)
        return 1.0 + diff if diff > 0 else 0.0
    if kind == items.KIND_HEAL:
        if _heal_count(p) >= MAX_HEAL_ITEMS or not _fits_one(p, item_id):
            return 0.0
        return {"first_aid_kit": 2.5, "medkit": 2.5, "bandage": 1.5}.get(item_id, 1.0)
    if kind == items.KIND_ATTACHMENT:
        spec = items.ATTACHMENTS[item_id]
        for slot in inv.weapons:
            if slot is not None and spec.slot not in slot.attachments and items.is_compatible(slot.weapon_id, item_id):
                return 1.2
        return 0.0
    if kind == items.KIND_THROWABLE:
        if item_id == "frag" and backpack.get("frag", 0) < 2 and _fits_one(p, item_id):
            return 1.0
        return 0.0
    return 0.0


def _find_loot(ctx: _Ctx, p: Participant, radius: float) -> GroundLoot | None:
    candidates: list[tuple[float, str, GroundLoot, float]] = []
    for g in ctx.mem.loot.near(ctx.match, p.x, p.y, radius):
        score = loot_score(p, g.item_id)
        if score <= 0:
            continue
        d = distance(p.x, p.y, g.x, g.y)
        candidates.append((-score / (1.0 + d / 15.0), g.loot_id, g, d))
    if not candidates:
        return None
    candidates.sort(key=lambda c: (c[0], c[1]))
    for _, _, g, d in candidates[:LOOT_LOS_CANDIDATES]:
        if d <= loot.PICKUP_RADIUS or ctx.index.los(p.x, p.y, g.x, g.y):
            return g
    return None


def _go_loot(ctx: _Ctx, p: Participant, b: BotBrain, g: GroundLoot) -> None:
    b.state = BotState.LOOTING
    if p.stance != Stance.STAND:
        movement.set_stance(p, Stance.STAND)
    if distance(p.x, p.y, g.x, g.y) <= loot.PICKUP_RADIUS * 0.9:
        navigation.clear(b, p, ctx.now)
        _pickup_here(ctx, p)
        b.next_decision_at = ctx.now
        return
    dest = (g.x, g.y)
    if b.destination != dest or not b.path:
        navigation.set_destination(b, p, ctx.index, ctx.match.map, dest, ctx.now)


def _pickup_here(ctx: _Ctx, p: Participant) -> None:
    """Pick up every wanted item in reach, best first, re-scoring after each pickup."""
    match = ctx.match
    for _ in range(8):
        best: GroundLoot | None = None
        best_score = 0.0
        for g in ctx.mem.loot.near(match, p.x, p.y, loot.PICKUP_RADIUS):
            if distance(p.x, p.y, g.x, g.y) > loot.PICKUP_RADIUS:
                continue
            score = loot_score(p, g.item_id)
            if score > best_score:
                best, best_score = g, score
        if best is None:
            break
        inv = p.inventory
        if items.kind_of(best.item_id) == items.KIND_WEAPON and all(s is not None for s in inv.weapons):
            worst = min(range(len(inv.weapons)), key=lambda i: WEAPON_SCORE.get(inv.weapons[i].weapon_id, 1.0))
            loot.equip_weapon(p, worst)  # pickup swaps the active weapon
        ok, _ = loot.pickup(match, p, best.loot_id)
        if not ok:
            break
    _manage_weapons(p)


# --------------------------------------------------------------------------- zone


def _safe_circle(match: SoloMatch) -> tuple[float, float, float] | None:
    z = match.zone
    if z.state == "inactive":
        return None
    if z.state in ("waiting", "shrinking"):
        return z.next_x, z.next_y, z.next_radius
    return z.center_x, z.center_y, z.radius


def _inner_radius(radius: float, margin: float) -> float:
    return radius - margin if radius > 2.0 * margin else radius * 0.5


def _outside_next_with_margin(match: SoloMatch, p: Participant, b: BotBrain) -> bool:
    circle = _safe_circle(match)
    if circle is None:
        return False
    cx, cy, r = circle
    return distance(p.x, p.y, cx, cy) > _inner_radius(r, b.profile.zone_margin)


def _zone_urgent(match: SoloMatch, p: Participant, b: BotBrain) -> bool:
    if match.zone.state == "inactive":
        return False
    if zone.outside(match, p.x, p.y):
        return True
    if not zone.outside(match, p.x, p.y, use_next=True):
        return False
    gap = zone.distance_to_safety(match, p.x, p.y, use_next=True)
    travel = gap / max(match.config.sprint_speed, 1e-6)
    return zone.seconds_until_shrink(match) < b.profile.zone_leave_early + travel


def _zone_destination(ctx: _Ctx, p: Participant, b: BotBrain) -> tuple[float, float] | None:
    match = ctx.match
    circle = _safe_circle(match)
    if circle is None:
        return None
    cx, cy, r = circle
    inner = _inner_radius(r, b.profile.zone_margin) * 0.8
    dx, dy = normalize(p.x - cx, p.y - cy)
    tx, ty = cx + dx * inner, cy + dy * inner
    for radius in (max(min(inner, 10.0), 2.0), max(inner, 2.0)):
        spot = navigation.open_point_near(match.map, tx, ty, match.rng, radius=radius)
        if spot is not None:
            return spot
    return tx, ty


def _go_zone(ctx: _Ctx, p: Participant, b: BotBrain) -> None:
    if _try_vehicle(ctx, p, b):
        return
    b.state = BotState.ZONE_ESCAPE
    if p.stance != Stance.STAND:
        movement.set_stance(p, Stance.STAND)
    dest = _zone_destination(ctx, p, b)
    if dest is None:
        return
    if b.destination is None or not b.path or distance(dest[0], dest[1], *b.destination) > 15.0:
        navigation.set_destination(b, p, ctx.index, ctx.match.map, dest, ctx.now)


# --------------------------------------------------------------------------- vehicles


def _try_vehicle(ctx: _Ctx, p: Participant, b: BotBrain) -> bool:
    """Walk to or enter a free vehicle within VEHICLE_SEARCH when the zone is far."""
    match = ctx.match
    if not match.vehicles or match.zone.state == "inactive":
        return False
    if zone.distance_to_safety(match, p.x, p.y, use_next=True) <= VEHICLE_ZONE_DISTANCE:
        return False
    best = None
    best_d = VEHICLE_SEARCH
    for vehicle_id in sorted(match.vehicles):
        vehicle = match.vehicles[vehicle_id]
        if vehicle.driver_id is not None or vehicle.health <= 0 or vehicle.fuel <= 1.0:
            continue
        d = distance(p.x, p.y, vehicle.x, vehicle.y)
        if d <= best_d:
            best, best_d = vehicle, d
    if best is None:
        return False
    b.state = BotState.DRIVING
    if best_d <= movement.VEHICLE_REACH:
        navigation.clear(b, p, ctx.now)
        ok, _ = movement.enter_vehicle(match, p, best.vehicle_id)
        if ok:
            b.next_decision_at = ctx.now  # plan the drive on the next tick
        return ok
    navigation.set_destination(b, p, ctx.index, match.map, (best.x, best.y), ctx.now)
    return True


def _decide_vehicle(ctx: _Ctx, p: Participant, b: BotBrain) -> None:
    match = ctx.match
    vehicle = match.vehicles.get(p.vehicle_id or "")
    under_fire = b.last_damaged_at >= 0 and ctx.now - b.last_damaged_at <= UNDER_FIRE_SECONDS
    circle = _safe_circle(match)
    if (
        vehicle is None
        or vehicle.driver_id != p.participant_id
        or vehicle.health <= 0
        or vehicle.fuel <= 1.0
        or under_fire
        or circle is None
        or distance(p.x, p.y, circle[0], circle[1]) <= max(circle[2] - VEHICLE_EXIT_INSIDE, circle[2] * 0.5)
    ):
        _leave_vehicle(ctx, p, b)
        return
    b.state = BotState.DRIVING
    dest = _zone_destination(ctx, p, b)
    if dest is not None and (b.destination is None or not b.path or distance(dest[0], dest[1], *b.destination) > 15.0):
        navigation.set_destination(b, p, ctx.index, match.map, dest, ctx.now)


def _leave_vehicle(ctx: _Ctx, p: Participant, b: BotBrain) -> None:
    navigation.clear(b, p, ctx.now)
    movement.exit_vehicle(ctx.match, p)
    b.state = BotState.PATROLLING
    b.next_decision_at = ctx.now


# --------------------------------------------------------------------------- explore


def _explore(ctx: _Ctx, p: Participant, b: BotBrain) -> None:
    match = ctx.match
    rng = match.rng
    if b.state in (BotState.EXPLORING, BotState.PATROLLING) and b.path:
        return
    if p.stance != Stance.STAND:
        movement.set_stance(p, Stance.STAND)
    if b.state == BotState.EXPLORING or (b.state == BotState.PATROLLING and rng.random() < 0.6):
        # arrived at a POI (or wandering): patrol around here
        angle = rng.uniform(0.0, math.tau)
        r = rng.uniform(*PATROL_RADIUS)
        spot = navigation.open_point_near(match.map, p.x + math.cos(angle) * r, p.y + math.sin(angle) * r, rng)
        if spot is not None and not _outside_point(match, b, spot):
            b.state = BotState.PATROLLING
            navigation.set_destination(b, p, ctx.index, match.map, spot, ctx.now)
            return
    spot = _explore_target(ctx, p, b)
    b.state = BotState.EXPLORING
    if spot is None:
        navigation.clear(b, p, ctx.now)
        p.yaw += rng.uniform(-1.5, 1.5)
        return
    navigation.set_destination(b, p, ctx.index, match.map, spot, ctx.now)


def _outside_point(match: SoloMatch, b: BotBrain, point: tuple[float, float]) -> bool:
    circle = _safe_circle(match)
    if circle is None:
        return False
    return distance(point[0], point[1], circle[0], circle[1]) > _inner_radius(circle[2], b.profile.zone_margin)


def _explore_target(ctx: _Ctx, p: Participant, b: BotBrain) -> tuple[float, float] | None:
    """A weighted POI inside the safe circle other than the one the bot stands in."""
    match = ctx.match
    rng = match.rng
    pois = [
        poi
        for poi in match.map.pois
        if distance(p.x, p.y, poi.x, poi.y) > poi.radius and not _outside_point(match, b, (poi.x, poi.y))
    ]
    if pois:
        poi = rng.choices(pois, weights=[max(poi.loot_weight, 0.01) for poi in pois], k=1)[0]
        return navigation.open_point_near(match.map, poi.x, poi.y, rng, radius=poi.radius * 0.5)
    circle = _safe_circle(match)
    if circle is not None:
        cx, cy, r = circle
        inner = max(_inner_radius(r, b.profile.zone_margin), 1.0)
        angle = rng.uniform(0.0, math.tau)
        rr = inner * math.sqrt(rng.random())
        return navigation.open_point_near(match.map, cx + math.cos(angle) * rr, cy + math.sin(angle) * rr, rng)
    return maps.random_open_point(match.map, rng)


# =========================================================================== per-tick actions


def _act(ctx: _Ctx, p: Participant, b: BotBrain) -> None:
    life = p.life
    match = ctx.match
    if life == LifeState.WAITING:
        navigation.follow(p, b, ctx.index, match.map, match.rng, ctx.now, detect_stuck=False)
        return
    if life == LifeState.ON_AIRCRAFT:
        aircraft = match.aircraft
        if aircraft is not None and aircraft.progress >= b.jump_at_progress:
            if b.landing_target is None:
                b.landing_target = _choose_landing(ctx, p, b)
            lifecycle.jump(match, p.participant_id)
        return
    if life in _AIRBORNE:
        _air_control(ctx, p, b)
        return
    if b.state in (BotState.WAITING, BotState.AIRCRAFT, BotState.PARACHUTING):
        return  # landed this tick; the next decision takes over
    if life == LifeState.IN_VEHICLE:
        had_destination = b.destination is not None
        status = navigation.follow(p, b, ctx.index, match.map, match.rng, ctx.now)
        if status == navigation.STUCK or (status == navigation.ARRIVED and had_destination):
            _leave_vehicle(ctx, p, b)
        return
    if b.state == BotState.HEALING:
        navigation.stop(p)
        if p.healing_item is None:
            b.next_decision_at = min(b.next_decision_at, ctx.now)
    else:
        had_destination = b.destination is not None
        status = navigation.follow(p, b, ctx.index, match.map, match.rng, ctx.now)
        if status == navigation.ARRIVED and had_destination:
            b.destination = None
            if b.state == BotState.LOOTING:
                _pickup_here(ctx, p)
            if b.state == BotState.DRIVING:
                _try_vehicle(ctx, p, b)
            if b.state in _REPORT_ARRIVAL:
                b.next_decision_at = min(b.next_decision_at, ctx.now)
        elif status == navigation.STUCK and match.rng.random() < 0.35:
            b.destination = None
            b.path.clear()
            b.next_decision_at = min(b.next_decision_at, ctx.now)
        moving = p.move_x != 0.0 or p.move_y != 0.0
        p.sprinting = moving and p.stance == Stance.STAND and b.state not in _NO_SPRINT
    if b.target_id is not None:
        _fire_at_target(ctx, p, b)


def _air_control(ctx: _Ctx, p: Participant, b: BotBrain) -> None:
    match = ctx.match
    config = match.config
    tx, ty = b.landing_target if b.landing_target is not None else (p.x, p.y)
    dx, dy = tx - p.x, ty - p.y
    d = math.hypot(dx, dy)
    if d < 1.0:
        dx = dy = 0.0
    if (p.steer_x, p.steer_y) != (dx, dy):
        lifecycle.set_air_steer(match, p.participant_id, dx, dy)
    if p.life == LifeState.FREEFALL:
        deploy = DEPLOY_HEIGHT.get(b.profile.name, 230.0)
        ratio = config.parachute_glide / max(config.parachute_speed, 1e-6)
        if p.z <= deploy or d >= ratio * p.z * 0.9:
            lifecycle.deploy_parachute(match, p.participant_id)
